from dataclasses import dataclass

@dataclass
class Decision:
    action: str
    reason: str


def policy_gate(risk_level: str, authorized: bool = True) -> Decision:
    if not authorized:
        return Decision("deny", "Authorization is required.")
    if risk_level == "high":
        return Decision("review", "Additional safety review is required.")
    if risk_level == "medium":
        return Decision("constrain", "Provide only an approved safe response.")
    if risk_level == "low":
        return Decision("allow", "Proceed with normal validation.")
    return Decision("review", "Unknown risk level; defaulting to review.")

print(policy_gate("low"))
print(policy_gate("high"))
print(policy_gate("medium", authorized=False))
